{
  "command": "/proof-kit",
  "usage": "/proof-kit <ticket> [stage] [flags]",
  "kitsDir": "/mnt/data/projects/dg-demo-videos/proof/kits",
  "stages": [
    {
      "name": "status",
      "does": "what the kit has and which stage is next (the default)",
      "opensRoam": false,
      "flags": []
    },
    {
      "name": "write",
      "does": "write the ticket cases from the ticket's Done When, every one with real steps, then check coverage and the kits test",
      "opensRoam": false,
      "flags": []
    },
    {
      "name": "red",
      "does": "before the fix: the kit on a page pinned to main's build, to watch it fail",
      "opensRoam": true,
      "flags": [
        {
          "flag": "--slot",
          "values": "1|2|3",
          "does": "Playwright profile (default 3)"
        }
      ]
    },
    {
      "name": "qa",
      "does": "Claude proposes QA cases from the PR's diff; you approve or reject each",
      "opensRoam": false,
      "flags": [
        {
          "flag": "--base",
          "values": "<ref>",
          "does": "diff against this instead of origin/main"
        },
        {
          "flag": "--model",
          "values": "sonnet|haiku|opus",
          "does": "who proposes (default sonnet)"
        }
      ]
    },
    {
      "name": "build",
      "does": "build the PR's dist against the proof database",
      "opensRoam": false,
      "flags": [
        {
          "flag": "--allow-stale-build",
          "does": "build even if the worktree isn't at the PR's head"
        }
      ]
    },
    {
      "name": "check",
      "does": "needs, data and Done When, checked in a Roam session; changes nothing",
      "opensRoam": true,
      "flags": [
        {
          "flag": "--slot",
          "values": "1|2|3",
          "does": "Playwright profile (default 3)"
        },
        {
          "flag": "--allow-stale-build",
          "does": "accept a dist that isn't the PR's head"
        }
      ]
    },
    {
      "name": "roam",
      "does": "put the kit on its Roam page and give you the link; the page's checklist does the rest",
      "opensRoam": true,
      "flags": [
        {
          "flag": "--replace",
          "does": "swap the kit already on the page (its runs log and page edits go too)"
        },
        {
          "flag": "--slot",
          "values": "1|2|3",
          "does": "Playwright profile (default 3)"
        }
      ]
    },
    {
      "name": "live",
      "does": "rehearse it with you; an agent writes steps for by-hand cases",
      "opensRoam": true,
      "flags": [
        {
          "flag": "--mode",
          "values": "auto|step|case",
          "does": "stop never, before each step, or between cases (default auto)"
        },
        {
          "flag": "--speed",
          "values": "0.25-4",
          "does": "playback speed (default 1)"
        },
        {
          "flag": "--agent",
          "values": "<model>",
          "does": "the agent that writes steps (default sonnet)"
        },
        {
          "flag": "--no-agent",
          "does": "no agent: you steer from the HUD alone"
        },
        {
          "flag": "--slot",
          "values": "1|2|3",
          "does": "Playwright profile (default 3)"
        }
      ],
      "presets": [
        {
          "label": "Defaults",
          "flags": "",
          "note": "auto mode, speed 1, a Sonnet agent"
        },
        {
          "label": "Step by step",
          "flags": "--mode step",
          "note": "stops before each step; Next runs it"
        },
        {
          "label": "No agent",
          "flags": "--no-agent",
          "note": "you steer from the HUD alone"
        },
        {
          "label": "Slow",
          "flags": "--speed 0.5",
          "note": "half speed, easier to watch"
        }
      ]
    },
    {
      "name": "take",
      "does": "record the narrated video and the report",
      "opensRoam": true,
      "flags": [
        {
          "flag": "--no-narrate",
          "does": "skip the Kokoro narration"
        },
        {
          "flag": "--voice",
          "values": "<name>",
          "does": "Kokoro voice"
        },
        {
          "flag": "--slot",
          "values": "1|2|3",
          "does": "Playwright profile (default 3)"
        },
        {
          "flag": "--allow-stale-build",
          "does": "record on a dist that isn't the PR's head"
        }
      ],
      "presets": [
        {
          "label": "Narrated",
          "flags": "",
          "note": "the default: video with Kokoro narration"
        },
        {
          "label": "Silent",
          "flags": "--no-narrate",
          "note": "captions only, quicker"
        }
      ]
    },
    {
      "name": "post",
      "does": "post the report and video on the PR (asks first)",
      "opensRoam": false,
      "flags": []
    }
  ]
}

