{
 "id": "dialog-renamed",
 "title": "The dialog and its command are called Import shared nodes",
 "steps": [
  {
   "id": "s1",
   "why": "open import the way a user would, from its renamed command",
   "source": "kit",
   "do": {
    "command_palette": "DG: Import shared nodes"
   }
  },
  {
   "id": "s2",
   "why": "wait for the import dialog",
   "source": "kit",
   "do": {
    "wait_for": ".bp3-dialog:visible"
   }
  },
  {
   "id": "s3",
   "why": "wait for the shared nodes to load",
   "source": "kit",
   "do": {
    "wait_for": ".bp3-dialog tbody tr:has-text(\"Daylight exposure resets the circadian clock\")"
   }
  },
  {
   "id": "s4",
   "why": "hold on the dialog title",
   "source": "kit",
   "do": {
    "pause": 1.5
   }
  }
 ],
 "proves": "Done When 8: Change the dialog title and entry points labeled \"Discover shared nodes\" to \"Import shared nodes\"",
 "checks": "the dialog title reads Import shared nodes and nothing on screen says Discover shared nodes",
 "caption": "The command and the dialog are now called Import shared nodes.",
 "expect": {
  "js": "proof.waitFor(() => { const dialog = proof.dialogs()[0]; const title = dialog && dialog.querySelector('.bp3-dialog-header'); return Boolean(title) && title.innerText.trim() === 'Import shared nodes' && !proof.dialogText().includes('Discover shared nodes'); }, { what: 'a dialog titled Import shared nodes' })"
 }
}
{
 "id": "columns-removed",
 "title": "The table has no status, source node ID or Source app column",
 "steps": [
  {
   "id": "s1",
   "why": "look at the column headers",
   "source": "kit",
   "do": {
    "pause": 1.5
   }
  }
 ],
 "proves": "Done When 2: The status, source node ID, and \"Source app\" columns are removed.",
 "checks": "the headers are exactly Source space, Title and Modified, and none of the removed columns is named",
 "caption": "Status, source node ID and Source app are gone. Source space, Title and Modified are left.",
 "expect": {
  "js": "(() => { const heads = Array.from(document.querySelectorAll('.bp3-dialog thead th')).map((cell) => cell.innerText.trim()).filter(Boolean); proof.assert(JSON.stringify(heads) === JSON.stringify(['Source space', 'Title', 'Modified']), 'The columns are ' + JSON.stringify(heads)); const text = proof.dialogText(); proof.assert(!/Status|Source app|Source node ID|Source ID/.test(text), 'A removed column is still on screen.'); })()"
 }
}
{
 "id": "dialog-height-fixed",
 "title": "The dialog keeps its height and its header and footer stay in view",
 "steps": [
  {
   "id": "s1",
   "why": "note the height with the table showing",
   "source": "kit",
   "do": {
    "js": "window.__dialogHeights = [Math.round(document.querySelector('.bp3-dialog').getBoundingClientRect().height)]"
   }
  },
  {
   "id": "s2",
   "why": "search for something nothing matches, so the table empties",
   "source": "kit",
   "do": {
    "fill": {
     "into": ".bp3-dialog input[placeholder=\"Search shared nodes\"]",
     "text": "no shared node has this text"
    }
   }
  },
  {
   "id": "s3",
   "why": "wait for the empty state",
   "source": "kit",
   "do": {
    "wait_for": ".bp3-dialog:has-text(\"No matching shared nodes\")"
   }
  },
  {
   "id": "s4",
   "why": "note the height with the table empty",
   "source": "kit",
   "do": {
    "js": "window.__dialogHeights.push(Math.round(document.querySelector('.bp3-dialog').getBoundingClientRect().height))"
   }
  },
  {
   "id": "s5",
   "why": "look at the dialog",
   "source": "kit",
   "do": {
    "pause": 1.5
   }
  },
  {
   "id": "s6",
   "why": "close the dialog before the next case",
   "source": "kit",
   "use": "dialog.close-all"
  }
 ],
 "proves": "Done When 9: The dialog keeps a fixed height as its contents change. Its contents scroll while the header and footer remain visible.",
 "checks": "the dialog is the same height with a full table and with an empty one, its header and footer lie inside the window, and the body between them is the part that scrolls",
 "caption": "The dialog stays the same height when the list empties out. The title and the buttons stay in view.",
 "expect": {
  "js": "(() => { const heights = window.__dialogHeights; proof.assert(heights.length === 2 && heights[0] === heights[1], 'The dialog height changed: ' + JSON.stringify(heights)); proof.assert(heights[0] <= window.innerHeight, 'The dialog is taller than the window.'); })()"
 }
}
{
 "id": "link-opens-the-page",
 "title": "Clicking a result opens the page and closes the dialog",
 "steps": [
  {
   "id": "s1",
   "why": "open the imported claim",
   "source": "kit",
   "do": {
    "click": ".bp3-dialog .bp3-callout li a:has-text(\"Daylight exposure\")"
   }
  },
  {
   "id": "s2",
   "why": "hold on the page",
   "source": "kit",
